# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MÜSLÜMANLARIN KARDEŞLİĞİ HADİS-İ ŞERİFİ VE İLKELERİ (1.8)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hadis-i Şerifin Temel Mesajları</text>\n  <text x="180" y="94" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">"Müslüman, Müslümanın kardeşidir..."</text>\n  <text x="180" y="116" text-anchor="middle" font-size="11" fill="#1e3a8a">• Kardeşine zulmetmez, haksızlık yapmaz.</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#1e3a8a">• Onu düşmana teslim etmez, yalnız bırakmaz.</text>\n  <text x="180" y="160" text-anchor="middle" font-size="11" fill="#1e3a8a">• Kardeşinin ihtiyacını giderenin ihtiyacını</text>\n  <text x="180" y="176" text-anchor="middle" font-size="11" fill="#1e3a8a">Allah giderir.</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" fill="#1e3a8a">• Sıkıntısını giderenin kıyamet sıkıntısını giderir.</text>\n  <text x="180" y="220" text-anchor="middle" font-size="11" fill="#1e3a8a">• Ayıbını ve kusurunu örtenin ayıbını Allah örter.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İslam Kardeşliğinin (Uhuvvet) Boyutları</text>\n  <text x="520" y="94" text-anchor="middle" font-size="11" fill="#14532d">• Hucurât 10: "Müminler ancak kardeştirler."</text>\n  <text x="520" y="116" text-anchor="middle" font-size="11" fill="#14532d">• Muâhât: Ensar ve Muhacir kardeşliği örneği</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" fill="#14532d">• Birbirine haset etmeme, küsmeme, gıybet etmeme</text>\n  <text x="520" y="160" text-anchor="middle" font-size="11" fill="#14532d">• Kendisi için istediğini kardeşi için de isteme</text>\n  <text x="520" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Bina ve Beden Benzetmesi:</text>\n  <text x="520" y="204" text-anchor="middle" font-size="10" fill="#14532d">Müminler kenetlenmiş bir binanın tuğlaları ve</text>\n  <text x="520" y="220" text-anchor="middle" font-size="10" fill="#14532d">tek bir bedenin organları (tarak dişleri) gibidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">VEDA HUTBESİ\'NDEKİ EVRENSEL İNSAN HAKLARI VE İLKELER (632)</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">1. Temel Haklar ve Eşitlik</text>\n  <text x="125" y="94" text-anchor="middle" font-size="10" fill="#713f12">• Can, mal ve namus</text>\n  <text x="125" y="110" text-anchor="middle" font-size="10" fill="#713f12">dokunulmazlığı esastır.</text>\n  <text x="125" y="134" text-anchor="middle" font-size="10" fill="#713f12">• Irkçılık ve soy üstünlüğü</text>\n  <text x="125" y="150" text-anchor="middle" font-size="10" fill="#713f12">reddedilmiştir.</text>\n  <text x="125" y="174" text-anchor="middle" font-size="10" font-weight="bold" fill="#854d0e">Üstünlük Ölçüsü:</text>\n  <text x="125" y="192" text-anchor="middle" font-size="10" fill="#713f12">Arap\'ın Arap olmayana</text>\n  <text x="125" y="208" text-anchor="middle" font-size="10" fill="#713f12">üstünlüğü yoktur; üstünlük</text>\n  <text x="125" y="224" text-anchor="middle" font-size="10" font-weight="bold" fill="#854d0e">TAKVA iledir.</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">2. Toplumsal Reformlar</text>\n  <text x="350" y="94" text-anchor="middle" font-size="10" fill="#881337">• Cahiliye adeti olan</text>\n  <text x="350" y="110" text-anchor="middle" font-size="10" font-weight="bold" fill="#9f1239">KAN DAVALARI kaldırıldı.</text>\n  <text x="350" y="134" text-anchor="middle" font-size="10" fill="#881337">• Haksız kazanç olan</text>\n  <text x="350" y="150" text-anchor="middle" font-size="10" font-weight="bold" fill="#9f1239">FAİZ (RİBA) yasaklandı.</text>\n  <text x="350" y="174" text-anchor="middle" font-size="10" fill="#881337">• Emanetlerin sahiplerine</text>\n  <text x="350" y="190" text-anchor="middle" font-size="10" fill="#881337">verilmesi emredildi.</text>\n  <text x="350" y="212" text-anchor="middle" font-size="10" font-weight="bold" fill="#be123c">• Kadınların hakları</text>\n  <text x="350" y="226" text-anchor="middle" font-size="10" fill="#881337">Allah\'ın emaneti sayıldı.</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">3. Bırakılan İki Emanet</text>\n  <text x="575" y="94" text-anchor="middle" font-size="10" fill="#164e63">"Size iki emanet bırakıyorum;</text>\n  <text x="575" y="110" text-anchor="middle" font-size="10" fill="#164e63">onlara sıkı sarıldıkça</text>\n  <text x="575" y="126" text-anchor="middle" font-size="10" fill="#164e63">yolunuzu şaşırmazsınız:"</text>\n  <text x="575" y="154" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">1. ALLAH\'IN KİTABI</text>\n  <text x="575" y="170" text-anchor="middle" font-size="10" fill="#155e75">(Kur\'an-ı Kerim)</text>\n  <text x="575" y="196" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">2. PEYGAMBERİN SÜNNETİ</text>\n  <text x="575" y="216" text-anchor="middle" font-size="10" fill="#155e75">Suçun şahsiliği ilkesi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN DİNİMİZDEKİ KONUMU VE GÖREVLERİ (2.1)</text>\n  <rect x="15" y="44" width="128" height="196" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="79" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">1. TEBLİĞ</text>\n  <text x="79" y="90" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e3a8a">Vahyi Ulaştırma</text>\n  <text x="79" y="114" text-anchor="middle" font-size="10" fill="#334155">Allah\'tan aldığı</text>\n  <text x="79" y="130" text-anchor="middle" font-size="10" fill="#334155">vahyi hiçbir ekleme</text>\n  <text x="79" y="146" text-anchor="middle" font-size="10" fill="#334155">veya çıkarma yapmadan</text>\n  <text x="79" y="162" text-anchor="middle" font-size="10" fill="#334155">insanlara bildirmesi.</text>\n  <text x="79" y="196" text-anchor="middle" font-size="9" font-weight="bold" fill="#1d4ed8">Mâide Suresi 67. Ayet</text>\n\n  <rect x="153" y="44" width="128" height="196" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="217" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">2. TEBYİN</text>\n  <text x="217" y="90" text-anchor="middle" font-size="10" font-weight="bold" fill="#14532d">Vahyi Açıklama</text>\n  <text x="217" y="114" text-anchor="middle" font-size="10" fill="#334155">Kur\'an\'da özet (mücmel)</text>\n  <text x="217" y="130" text-anchor="middle" font-size="10" fill="#334155">geçen ibadet ve</text>\n  <text x="217" y="146" text-anchor="middle" font-size="10" fill="#334155">ayetleri söz ve</text>\n  <text x="217" y="162" text-anchor="middle" font-size="10" fill="#334155">uygulamayla açıklaması.</text>\n  <text x="217" y="196" text-anchor="middle" font-size="9" font-weight="bold" fill="#15803d">Nahl Suresi 44. Ayet</text>\n\n  <rect x="291" y="44" width="128" height="196" rx="8" fill="#fef9c3" stroke="#ca8a04" stroke-width="1.5"/>\n  <text x="355" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">3. TEŞRİ</text>\n  <text x="355" y="90" text-anchor="middle" font-size="10" font-weight="bold" fill="#854d0e">Hüküm Koyma</text>\n  <text x="355" y="114" text-anchor="middle" font-size="10" fill="#334155">Kur\'an\'da açıkça</text>\n  <text x="355" y="130" text-anchor="middle" font-size="10" fill="#334155">yer almayan konularda</text>\n  <text x="355" y="146" text-anchor="middle" font-size="10" fill="#334155">vahyin ışığında dinî</text>\n  <text x="355" y="162" text-anchor="middle" font-size="10" fill="#334155">hüküm belirlemesi.</text>\n  <text x="355" y="196" text-anchor="middle" font-size="9" font-weight="bold" fill="#a16207">A\'râf 157 · Haşr 7</text>\n\n  <rect x="429" y="44" width="128" height="196" rx="8" fill="#f3e8ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="493" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">4. TEMSİL</text>\n  <text x="493" y="90" text-anchor="middle" font-size="10" font-weight="bold" fill="#6b21a8">Örnek Olma</text>\n  <text x="493" y="114" text-anchor="middle" font-size="10" fill="#334155">Tebliğ ettiği ilkeleri</text>\n  <text x="493" y="130" text-anchor="middle" font-size="10" fill="#334155">önce kendi hayatında</text>\n  <text x="493" y="146" text-anchor="middle" font-size="10" fill="#334155">yaşayarak müminlere</text>\n  <text x="493" y="162" text-anchor="middle" font-size="10" fill="#334155">en güzel örnek olması.</text>\n  <text x="493" y="196" text-anchor="middle" font-size="9" font-weight="bold" fill="#7e22ce">Ahzâb 21 (Üsve-i Hasene)</text>\n\n  <rect x="567" y="44" width="118" height="196" rx="8" fill="#ffe4e6" stroke="#e11d48" stroke-width="1.5"/>\n  <text x="626" y="66" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">5. TEZKİYE</text>\n  <text x="626" y="90" text-anchor="middle" font-size="10" font-weight="bold" fill="#9f1239">Arındırma</text>\n  <text x="626" y="114" text-anchor="middle" font-size="10" fill="#334155">İnsanların kalplerini</text>\n  <text x="626" y="130" text-anchor="middle" font-size="10" fill="#334155">şirk, kin ve kötü</text>\n  <text x="626" y="146" text-anchor="middle" font-size="10" fill="#334155">huylardan temizleyip</text>\n  <text x="626" y="162" text-anchor="middle" font-size="10" fill="#334155">olgunlaştırması.</text>\n  <text x="626" y="196" text-anchor="middle" font-size="9" font-weight="bold" fill="#be123c">Cuma Suresi 2. Ayet</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
